async fn multipart(r:Request)->Result<String,maximus::Error>{let mut m=r.multipart(1048576,1048576)?;let f=m.next_field().await.map_err(|_|maximus::Error::bad_request("multipart"))?.ok_or_else(||maximus::Error::bad_request("missing field"))?;let s=f.text().await.map_err(|_|maximus::Error::bad_request("multipart"))?;Ok(s)}
