 let mut s=maximus::Server::new("0.0.0.0:8080".parse()?).workers(maximus::WorkerConfig {workers:1,backend:maximus::Backend::IoUring,..Default::default()}).limits(maximus::Limits {requests_per_connection:usize::MAX,memory_bytes:4*1024*1024*1024,..Default::default()});
 if let Ok(cert)=std::env::var("MAXIMUS_CERT"){s=s.tls(maximus::TlsConfig::from_pem(&std::fs::read(cert)?,&std::fs::read(std::env::var("MAXIMUS_KEY")?)?,std::env::var("PROTOCOL").as_deref()==Ok("h2"))?);}
 let server=s.start(||maximus::routes!{GET "/plaintext"=>plain,POST "/echo"=>echo,POST "/json"=>json,POST "/multipart"=>multipart,GET "/sse"=>sse,GET "/stream"=>stream,GET "/multi/{id}"=>multi,POST "/multi/{name}"=>multi,PUT "/multi/{value}"=>multi})?;
 eprintln!("ready");server.wait()?;Ok(())
}

