source='''use maximus::{Body,Handler,Request};
fn ready<T>(f:impl std::future::Future<Output=T>)->T {let mut f=std::pin::pin!(f);match f.as_mut().poll(&mut std::task::Context::from_waker(std::task::Waker::noop())){std::task::Poll::Ready(v)=>v,_=>panic!()}}
async fn body(_:Request)->Body {"ok".into()}
fn main(){ let routes=maximus::routes!{ ROUTES };
for i in 0..64 { for method in ["GET","HEAD","POST","PUT","PATCH"] {
 let request=Request::new(maximus::http::Request::builder().method(method).uri(format!("/items/{i}")).body(Body::empty()).unwrap());
 let response=ready(routes.handle(std::hint::black_box(request)));
 assert_eq!(response.status().as_u16(),if method=="PATCH" {405}else{200});
 if method=="PATCH" {assert_eq!(response.headers()["allow"],"GET, HEAD, POST, PUT");}
}} println!("320 dispatches across 192 routes passed");}
'''.replace('ROUTES',','.join(f'{m} "/items/{i}"=>body' for i in range(64) for m in ['GET','POST','PUT']))
